mapper.select:
select v.id, v.order_id, v.user_id, v.result, v.reason, v.like_count, v.create_time, u.nick_name as user_nick_name, u.avatar as user_avatar, case when vl.id is null then 0 else 1 end as liked from apply_vote v left join app_user u on u.id = v.user_id and u.del_flag = '0' left join apply_vote_like vl on vl.vote_id = v.id and vl.user_id = #{userId} where v.del_flag = '0' and v.order_id = #{orderId}
order by v.like_count desc, v.create_time desc
order by v.create_time desc

select
    v.id, v.order_id, v.user_id, v.result, v.reason, v.like_count, v.create_time,
    u.nick_name as user_nick_name,
    u.avatar    as user_avatar
from apply_vote v
left join app_user u on u.id = v.user_id and u.del_flag = '0'
where v.del_flag = '0'

    and v.id = #{bo.id}


    and v.order_id = #{bo.orderId}


    and v.user_id = #{bo.userId}


    and v.result = #{bo.result}


    and v.reason like concat('%', #{bo.keyword}, '%')


    and v.create_time >= #{bo.beginTime}


    and v.create_time <= #{bo.endTime}

order by v.create_time desc
